// ---------------------------------------------------------------------------
// nnue_embedded.hpp - the network compiled into the binary.
//
// `src/evaluation/nnue_net_data.cpp` is generated by scripts/embed_nnue.py from
// a .nnue file produced by the training pipeline; it must not be edited by hand.
// A build without a trained network defines a zero-length blob, in which case
// the engine keeps using the classical evaluation and the UCI handshake says so.
// ---------------------------------------------------------------------------
#pragma once

#include <cstddef>
#include <cstdint>

namespace stockbear::nnue {
// Length in bytes; zero when this build embeds no network.
extern const std::size_t kEmbeddedNetSize;
// Pointer to the serialised network (never null, but undefined when the size is
// zero). Kept separate from the size so that the loader can reject a truncated
// blob the same way it rejects a truncated file.
extern const std::uint8_t* const kEmbeddedNetData;
} // namespace stockbear::nnue
